pub fn rib_a(buf: &[u8], pos: u32, n: u32) -> u32 {
    if n == 0 || n > 32 {
        return 0;
    }
    let end = match pos.checked_add(n) {
        Some(v) => v,
        None => return 0,
    };
    if (end as usize) > buf.len().saturating_mul(8) {
        return 0;
    }

    let mut value = 0u32;
    for p in pos..end {
        let octet = buf[(p / 8) as usize];
        let bit = (octet >> (7 - (p % 8))) & 1;
        value = (value << 1) | bit as u32;
    }
    value
}
